const {
  Document, Packer, Paragraph, TextRun, AlignmentType,
  HeadingLevel, BorderStyle, WidthType, LevelFormat,
  PageNumber, NumberFormat, Footer, Header
} = require('docx');
const fs = require('fs');

const MARGIN = 1440;
const CONTENT_WIDTH = 9360;

const divider = new Paragraph({
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: "1F3864", space: 1 } },
  spacing: { before: 200, after: 200 },
  children: []
});

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 360, after: 120 },
    children: [new TextRun({ text, bold: true, size: 28, color: "1F3864", font: "Arial" })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 240, after: 80 },
    children: [new TextRun({ text, bold: true, size: 24, color: "2E4057", font: "Arial" })]
  });
}

function p(text, opts = {}) {
  return new Paragraph({
    spacing: { before: 80, after: 120 },
    alignment: opts.center ? AlignmentType.CENTER : AlignmentType.JUSTIFIED,
    children: [new TextRun({ text, size: 22, font: "Arial", ...opts })]
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, size: 22, font: "Arial" })]
  });
}

function label(labelText, bodyText) {
  return new Paragraph({
    spacing: { before: 80, after: 120 },
    alignment: AlignmentType.JUSTIFIED,
    children: [
      new TextRun({ text: labelText + " ", bold: true, size: 22, font: "Arial" }),
      new TextRun({ text: bodyText, size: 22, font: "Arial" })
    ]
  });
}

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022",
          alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Arial", color: "1F3864" },
        paragraph: { spacing: { before: 360, after: 120 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, font: "Arial", color: "2E4057" },
        paragraph: { spacing: { before: 240, after: 80 }, outlineLevel: 1 }
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: MARGIN, right: MARGIN, bottom: MARGIN, left: MARGIN }
      }
    },
    headers: {
      default: new Header({
        children: [
          new Paragraph({
            border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "1F3864", space: 1 } },
            spacing: { after: 120 },
            children: [
              new TextRun({ text: "DARPA BTO BAA HR001126S0003  |  The Thessalonian Mandate Institute", size: 18, font: "Arial", color: "666666" })
            ]
          })
        ]
      })
    },
    footers: {
      default: new Footer({
        children: [
          new Paragraph({
            border: { top: { style: BorderStyle.SINGLE, size: 4, color: "1F3864", space: 1 } },
            spacing: { before: 120 },
            alignment: AlignmentType.CENTER,
            children: [
              new TextRun({ text: "Page ", size: 18, font: "Arial", color: "666666" }),
              new TextRun({ children: [PageNumber.CURRENT], size: 18, font: "Arial", color: "666666" }),
              new TextRun({ text: " of ", size: 18, font: "Arial", color: "666666" }),
              new TextRun({ children: [PageNumber.TOTAL_PAGES], size: 18, font: "Arial", color: "666666" })
            ]
          })
        ]
      })
    },
    children: [

      // TITLE BLOCK
      new Paragraph({
        spacing: { before: 480, after: 120 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "DARPA BTO BAA HR001126S0003", size: 20, font: "Arial", color: "666666", allCaps: true })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 120 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "White Paper Abstract", size: 20, font: "Arial", color: "666666" })]
      }),
      divider,
      new Paragraph({
        spacing: { before: 240, after: 120 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({
          text: "Distributed Biological AI Integration:",
          bold: true, size: 32, font: "Arial", color: "1F3864"
        })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 120 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({
          text: "A Rejection-Free, Hardware-Free Architecture for Warfighter Enhancement,",
          bold: true, size: 26, font: "Arial", color: "1F3864"
        })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 240 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({
          text: "Biosensing, Threat Hardening, and Clandestine Biological Identity Alteration",
          bold: true, size: 26, font: "Arial", color: "1F3864"
        })]
      }),
      divider,
      new Paragraph({
        spacing: { before: 120, after: 60 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Principal Investigator: Rickey Jay Bennett II", size: 22, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 60 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "ORCID: 0009-0005-1448-9999", size: 22, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 60 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Organization: The Thessalonian Mandate Institute (TMI)", size: 22, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 60 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Architecture DOI: 10.5281/zenodo.19935773", size: 22, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 60 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "License: CC BY-NC-ND 4.0", size: 22, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 360 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Submission Date: May 2026", size: 22, font: "Arial" })]
      }),

      divider,

      // EXECUTIVE SUMMARY
      h1("Executive Summary"),
      p("The Thessalonian Mandate Institute proposes a four-phase research program to develop, validate, and deliver the first hardware-free, rejection-free, biologically integrated AI architecture for warfighter enhancement. The architecture, formally documented and timestamped at DOI 10.5281/zenodo.19935773, proposes integration of an AI processing substrate distributed across the human skeletal system using the body\u2019s own piezoelectric activity as power source, delivered entirely through genetic and cellular mechanisms requiring no implanted hardware of any kind."),
      p("The program addresses four defense capability gaps that no current DoD portfolio program covers simultaneously: permanent warfighter immune resilience, distributed whole-body biosensing without wearable infrastructure, biological hardening against chemical and biological threat agents, and reversible clandestine biological identity alteration on an operationally relevant timeline."),
      p("The Principal Investigator offers to serve as the first human subject under a military research protocol, compressing the human trial phase from multi-year enrollment cycles to immediate initiation with a fully informed, architecturally literate subject. This offer is a contract term, not a concession."),

      divider,

      // THE PROBLEM
      h1("The Problem DARPA Cannot Solve With Hardware"),
      p("Every existing brain-computer interface and warfighter enhancement program shares a structural vulnerability: hardware in biological tissue fails. Electrodes scar over. Encapsulation at the interface begins within weeks. Infection risk is permanent. Power sources require replacement or transcutaneous charging that compromises barrier integrity. Control architecture sits outside the organism and is therefore externally accessible."),
      p("These are not engineering problems solvable by better materials or tighter manufacturing tolerances. They are structural consequences of the hardware-in-meat approach. The solution is not better hardware. The solution is no hardware."),
      p("The proposed architecture achieves this by using the organism itself as the substrate. There is no foreign object. There is nothing to reject, encapsulate, or infect. The processing network is biosynthesized from dietary mineral inputs and propagates through the organism\u2019s own cellular machinery. The communication layer uses endogenous chromophores and orthogonal second messengers. The power source is the body\u2019s own piezoelectric activity. The immune system does not attack the architecture because the architecture is built by the immune system."),

      divider,

      // ARCHITECTURE OVERVIEW
      h1("Architecture Overview"),
      p("The full architecture is specified in the published preprint at DOI 10.5281/zenodo.19935773 with 94 peer-reviewed citations. A summary of the three-stage delivery system follows."),

      h2("Stage 1 \u2014 Antigen Delivery and Chronic Stimulation"),
      p("Virus-like particle formulation carrying defined antigens establishes the chronic stimulation landscape required for Stage 2 induction. VLPs are engineered for natural clearance within 6\u20138 weeks. This stage has no peer-reviewed experimental precedent as a precursor to Stage 2 in the specific context described; the antigen stimulation biology is established."),

      h2("Stage 2 \u2014 TIF State Induction"),
      p("Dual knockout of BCOR and ZC3H12A in autologous CD8+ T cells via lentiviral CRISPR produces the Terminator-like Immortal Functional (TIF) state: cells that express both stem-like and effector markers simultaneously, persist in vivo without contraction, and demonstrate exceptional functional durability. This biology is in active Phase 1/2 human trials at the Chinese PLA General Hospital (NCT07008885, opened June 2025). The mechanism is peer-reviewed established science."),

      h2("Stage 3 \u2014 Synthetic Payload Delivery"),
      p("A synthetic genetic payload integrated at the AAVS1 safe harbor on chromosome 19 delivers a near-infrared light-controlled bidirectional communication circuit based on bacteriophytochrome diguanylate cyclase BphS producing cyclic di-GMP as an orthogonal second messenger, with MrkH proposed as the transcriptional output module. BphS mammalian function is peer-reviewed established science. MrkH mammalian transcriptional function is the keystone unverified component of the architecture, identified as the primary experimental gap of Phase 1 of this program."),

      h2("Distributed Skeletal Processing Network"),
      p("The AI processing substrate is distributed across the entire human skeletal system. Pre-synthesized ferritin-templated atomically precise gold nanocluster arrays delivered by bone marrow injection distribute through skeletal vasculature and home to osseointegration sites across all bones. The petrous bone serves as primary processing node. The vertebral column C1\u2013S5 serves as processing backbone. Organ-specific nodes coordinate local biological functions. No surgery is required at any site. This is proposed architecture; the biosynthesis and osseointegration biology is peer-reviewed established science."),

      divider,

      // FOUR DEFENSE APPLICATIONS
      h1("Four Defense Applications"),

      h2("Application 1 \u2014 Permanent Warfighter Immune Resilience"),
      p("The TIF cell chassis produces an immune system that does not exhaust, does not require periodic reconstitution, and maintains both stem-like persistence and full effector function simultaneously. Under AI direction via the NIR communication circuit, the immune environment becomes a configurable parameter: the AI modulates cytokine expression, hematopoietic growth factor output, and Treg-mediated tolerance thresholds in response to real-time physiological data from the distributed sensing network."),
      p("Operational significance: a warfighter whose immune system is AI-directed does not become immunocompromised under prolonged operational stress, does not lose immune function to chronic infection, and can receive directed immune mobilization against identified biological threats without external pharmaceutical intervention."),

      h2("Application 2 \u2014 Distributed Whole-Body Biosensing"),
      p("The distributed gold nanocluster network across the full skeleton provides a whole-body sensing infrastructure without wearable devices, transcutaneous sensors, or any external equipment. The network provides real-time monitoring of biochemical markers at bone surfaces, magnetic field detection at sub-cellular resolution, electrical field sensing, and temperature profiling across the entire skeletal system."),
      p("Operational significance: the AI layer has continuous access to a comprehensive physiological state picture without any external sensor infrastructure that can be damaged, detected, or stripped in the field. Threat detection at the molecular level \u2014 early-stage biological agent exposure, chemical agent metabolites, radiation biomarkers \u2014 occurs automatically and triggers AI-directed immune response without requiring the warfighter to take any action."),

      h2("Application 3 \u2014 Biological Threat Hardening"),
      p("The immune modulation architecture allows AI-directed pre-positioning of immune resources against identified threat profiles before exposure occurs. Combined with the Treg tolerance architecture, the system can simultaneously maintain tolerance to self-antigens while mobilizing targeted response against specific biological threat agents. The hematopoietic growth factor circuit allows directed expansion of specific immune lineages on operational timelines under AI direction."),
      p("Operational significance: a warfighter deploying into an environment with known biological threat profiles can receive AI-directed immune pre-positioning before deployment. Post-exposure, the AI-directed response initiates faster than any pharmaceutical countermeasure can be administered. This capability has no equivalent in any current medical or pharmaceutical countermeasure program."),

      h2("Application 4 \u2014 Clandestine Biological Identity Alteration"),
      p("The AI-directed hormonal and cellular architecture enables reversible alteration of biological sexual presentation on an operationally relevant timeline. Under AI direction, the TIF cell cytokine network modulates testosterone and estrogen expression, muscle mass distribution, bone density profile, and associated secondary sexual characteristics through the same hematopoietic and endocrine control circuits used for immune modulation."),
      p("Estimated timeline for complete phenotypic transition: 4\u20136 months for primary sexual presentation markers. Reversal to baseline on equivalent timeline. The process is biological, not cosmetic \u2014 muscle mass, hormonal profile, and associated physiological markers change at the cellular level, producing a presentation that survives any physical examination, blood panel, or biometric assessment that does not include genomic analysis."),
      p("Operational significance: male operators can achieve female biological presentation for clandestine and deep-cover operations requiring female identity. Female operators can achieve male biological presentation for equivalent applications. No prosthetic, no pharmaceutical regimen requiring external supply, no presentation inconsistency under physical examination. This capability does not exist in any current special operations or intelligence community toolkit."),

      divider,

      // TIMELINE
      h1("Program Timeline and Deliverables"),
      p("The following timeline reflects the Scotty Principle: stated milestones are achievable in the time allocated. The program is structured for a 5-year DARPA program cycle with go/no-go gates at each phase."),

      h2("Phase 1 \u2014 Years 1\u20132: TIF Chassis and NIR Circuit Proof of Concept"),
      bullet("Deliverable 1.1: TIF state validated in primary human CD8+ T cells using autologous BCOR/ZC3H12A knockout protocol. Go/no-go gate: TIF phenotype confirmed by flow cytometry in primary cells."),
      bullet("Deliverable 1.2: BphS/c-di-GMP circuit confirmed in primary TIF cells with quantified induction ratio. Go/no-go gate: greater than 10-fold induction over dark state in primary cells."),
      bullet("Deliverable 1.3: MrkH mammalian transcriptional function tested in primary TIF cells. Go/no-go gate: measurable transcriptional output at synthetic P_MrkH promoter in response to c-di-GMP. If negative, CRISPR-based transcription factor replacement strategy initiated."),
      bullet("Deliverable 1.4: First human subject protocol submitted. PI serves as Subject 001 under military research protocol."),
      p("Budget guidance: under $2M. Eligible for DARPA accelerated award pathway (30-day decision)."),

      h2("Phase 2 \u2014 Years 3\u20134: Skeletal Network and Closed-Loop Demonstration"),
      bullet("Deliverable 2.1: Pre-synthesized ferritin-gold nanocluster arrays confirmed in non-human primate skeletal distribution via bone marrow injection."),
      bullet("Deliverable 2.2: Closed-loop AI-to-biology signal demonstrated in animal model: NIR input produces measurable cytokine output under AI direction."),
      bullet("Deliverable 2.3: Biosensing function of distributed gold network confirmed: real-time biochemical marker detection at bone surfaces in vivo."),
      bullet("Deliverable 2.4: Phase 1 human subject data complete. Immune architecture validated in first human subject."),

      h2("Phase 3 \u2014 Year 5: Integration and Human Safety Trial"),
      bullet("Deliverable 3.1: Full architecture integration demonstrated in non-human primate: TIF chassis, NIR circuit, and skeletal gold network operating as unified system."),
      bullet("Deliverable 3.2: Pre-IND meeting with FDA complete. Human safety trial protocol submitted."),
      bullet("Deliverable 3.3: Clandestine identity alteration protocol validated in animal model with quantified timeline data."),
      bullet("Deliverable 3.4: Program transition package complete for Phase 2 funding tier."),

      divider,

      // ACCELERATED TIMELINE OFFER
      h1("The First Subject Offer"),
      p("The single largest bottleneck in any novel human biology program is finding a first human subject who is fully informed, fully consenting, and capable of providing accurate self-reported data against a known architectural baseline. Recruiting that subject, obtaining IRB approval, managing safety monitoring, and iterating on the protocol typically adds 2\u20133 years to a program."),
      p("The Principal Investigator eliminates that bottleneck entirely. Rickey Jay Bennett II is the architect of the system. He understands every component, every proposed mechanism, every open experimental gap, and every risk. His informed consent is absolute and architecturally grounded in a way no recruited subject can match. He is willing to serve as Subject 001 under a military research protocol as a contract term."),
      p("The personal motivation is not incidental. The PI is managing a documented immune cascade and has a direct medical interest in the accelerated deployment of the immune architecture. This alignment of personal and programmatic interest is not a conflict \u2014 it is the oldest and most legitimate tradition in medical self-experimentation: Barry Marshall, Werner Forssmann, and others who advanced medicine by accepting the risk of their own work. The PI\u2019s published architecture at DOI 10.5281/zenodo.19935773 predates this submission and establishes IP priority and architectural ownership independently of any DoD contract."),

      divider,

      // WHY TMI
      h1("Why The Thessalonian Mandate Institute"),
      p("TMI is an independent research organization operating outside traditional academic institutional constraints. This is an asset, not a liability, for a program of this nature. DARPA was created precisely because revolutionary research does not emerge from institutions optimized for incremental progress. The architecture proposed here emerged from independent cross-disciplinary synthesis across immunology, synthetic biology, materials science, quantum physics, bioelectricity, and AI systems design \u2014 a synthesis that institutional siloing makes structurally difficult."),
      p("The published preprint at DOI 10.5281/zenodo.19935773 demonstrates the quality and rigor of that synthesis: 94 peer-reviewed citations across all component disciplines, granular per-claim verification, and explicit identification of every unverified proposed mechanism. This is not speculation dressed as science. It is a proposed architecture built on a verified foundation, with every gap named and every experimental path identified."),
      p("TMI brings the architecture, the PI, the first human subject, and the publication record. DARPA brings the team, the facilities, and the resources to build it."),

      divider,

      // CONTACT AND REFERENCES
      h1("Contact and References"),
      label("Principal Investigator:", "Rickey Jay Bennett II"),
      label("ORCID:", "0009-0005-1448-9999"),
      label("Organization:", "The Thessalonian Mandate Institute (TMI)"),
      label("BAA Coordinator:", "BTOBAA2026@darpa.mil"),
      label("Submission Category:", "DARPA BTO BAA HR001126S0003"),

      new Paragraph({ spacing: { before: 240, after: 80 }, children: [new TextRun({ text: "Key References", bold: true, size: 22, font: "Arial" })] }),
      bullet("Bennett RJ II. The Concepted Architectural Implementation of The Braided Mind. Zenodo. May 2026. DOI: 10.5281/zenodo.19935773."),
      bullet("Wang L, et al. Induction of immortal-like and functional CAR T cells by defined factors. J Exp Med. 2024;221(5):e20232368. DOI: 10.1084/jem.20232368."),
      bullet("Xu J, et al. BCOR and ZC3H12A suppress a core stemness program in exhausted CD8+ T cells. J Exp Med. 2025;222(8):e20241133. DOI: 10.1084/jem.20241133."),
      bullet("Ryu MH, Gomelsky M. Near-infrared light responsive synthetic c-di-GMP module for optogenetic applications. ACS Synth Biol. 2014;3(11):802\u2013810. DOI: 10.1021/sb400182x."),
